from phase0_v2.conflicts.preprocessing import extract_content

def _score_short_sentences(text: str) -> float:
    cleaned = extract_content(text, 'short_vs_long_sentences') or text
    avg = _avg_sentence_length(cleaned)
    if avg == 0.0:
        return 1.0
    return 1.0 / (1.0 + math.exp(_STEEPNESS * (avg - _MIDPOINT)))
